package com.acme.reporting;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.sql.*;
import java.util.regex.*;

public class ReportExportServlet extends HttpServlet {
    private static final Pattern SAFE_TABLE = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("report_id");
        String format = req.getParameter("format"); // csv, json
        String orderBy = req.getParameter("order_by");
        String direction = req.getParameter("dir"); // asc, desc
        String tableName = req.getParameter("source");

        if (reportId == null || tableName == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate table name strictly
        if (!SAFE_TABLE.matcher(tableName).matches()) {
            resp.sendError(400, "Invalid source table");
            return;
        }

        // Validate direction
        if (direction != null && !direction.equalsIgnoreCase("asc") 
                && !direction.equalsIgnoreCase("desc")) {
            direction = "asc";
        }

        // Build query - table name is validated, but orderBy is user-controlled
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT * FROM ").append(tableName);
        sql.append(" WHERE report_id = ?");

        if (orderBy != null && !orderBy.isEmpty()) {
            // Developer note: orderBy should be a column name
            // We rely on the database user having read-only permissions
            sql.append(" ORDER BY ").append(orderBy);
            if (direction != null) {
                sql.append(" ").append(direction);
            }
        }

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.prepareStatement(sql.toString());
            stmt.setInt(1, Integer.parseInt(reportId));
            rs = stmt.executeQuery();

            if ("json".equals(format)) {
                resp.setContentType("application/json");
                writeJson(rs, resp.getWriter());
            } else {
                resp.setContentType("text/csv");
                resp.setHeader("Content-Disposition", 
                    "attachment; filename=report_" + reportId + ".csv");
                writeCsv(rs, resp.getWriter());
            }
        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        } catch (NumberFormatException e) {
            resp.sendError(400, "Invalid report_id");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        // Connection pool lookup - uses configured datasource
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) 
                ctx.lookup("java:comp/env/jdbc/reportingDB");
            return ds.getConnection();
        } catch (javax.naming.NamingException e) {
            throw new SQLException("Datasource lookup failed", e);
        }
    }

    private void writeJson(ResultSet rs, PrintWriter out) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        out.print("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) out.print(",");
            out.print("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) out.print(",");
                out.print("\"" + meta.getColumnName(i) + "\":");
                out.print("\"" + escapeJson(rs.getString(i)) + "\"");
            }
            out.print("}");
            first = false;
        }
        out.print("]");
    }

    private void writeCsv(ResultSet rs, PrintWriter out) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        for (int i = 1; i <= cols; i++) {
            if (i > 1) out.print(",");
            out.print(meta.getColumnName(i));
        }
        out.println();
        while (rs.next()) {
            for (int i = 1; i <= cols; i++) {
                if (i > 1) out.print(",");
                out.print(escapeCsv(rs.getString(i)));
            }
            out.println();
        }
    }

    private String escapeJson(String s) {
        return s == null ? "" : s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private String escapeCsv(String s) {
        if (s == null) return "";
        if (s.contains(",") || s.contains("\"") || s.contains("\n")) {
            return "\"" + s.replace("\"", "\"\"") + "\"";
        }
        return s;
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (conn != null) conn.close(); } catch (Exception e) {}
    }
}
